Here's a simple expense tracker: add what you spent, pick a category, and it shows your total and a split by category for the month. Your entries stay in this page, and are saved on this device if your app allows it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f4;color:#222}
  h2{margin:0 0 12px;font-size:20px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box}
  input,select{flex:1;min-width:110px}
  button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
  button.del{background:none;color:#b00020;padding:2px 8px}
  .total{font-size:26px;font-weight:600}
  .bar{height:8px;background:#2f7d5b;border-radius:4px}
  .cat{margin:8px 0}
  .cat div.l{display:flex;justify-content:space-between;font-size:14px}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
  .muted{color:#777;font-size:12px}
  .over{color:#b00020}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <input id="month" type="month">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div class="total" id="total">₹0</div>
  <div class="muted" id="left"></div>
</div>

<div class="card">
  <div class="row">
    <input id="desc" type="text" placeholder="What was it for?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
    </select>
    <input id="date" type="date">
    <button type="button" id="add">Add</button>
  </div>
</div>

<div class="card"><b>By category</b><div id="cats"></div></div>
<div class="card"><b>Entries</b><div id="list"></div></div>

<script>
var KEY="foo_expenses_v1", data={items:[],budget:""};
try{var s=localStorage.getItem(KEY);if(s)data=JSON.parse(s);}catch(e){}
var $=function(i){return document.getElementById(i)};
var today=new Date().toISOString().slice(0,10);
$("date").value=today;
$("month").value=today.slice(0,7);
$("budget").value=data.budget||"";

function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){}}

function render(){
  var m=$("month").value;
  var items=data.items.filter(function(x){return x.date.slice(0,7)===m})
    .sort(function(a,b){return a.date<b.date?1:-1});
  var total=items.reduce(function(a,x){return a+x.amt},0);
  $("total").textContent=inr(total);
  var b=parseFloat($("budget").value),left=$("left");
  if(b>0){
    var d=b-total;
    left.textContent=d>=0?inr(d)+" left of "+inr(b):inr(-d)+" over budget";
    left.className=d>=0?"muted":"muted over";
  }else{left.textContent="Add a budget to see what's left";left.className="muted"}

  var by={};items.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt});
  var cats=$("cats");cats.innerHTML="";
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(c){
    var w=document.createElement("div");w.className="cat";
    var l=document.createElement("div");l.className="l";
    var a=document.createElement("span");a.textContent=c;
    var v=document.createElement("span");v.textContent=inr(by[c]);
    l.appendChild(a);l.appendChild(v);
    var bar=document.createElement("div");bar.className="bar";
    bar.style.width=(total?by[c]/total*100:0)+"%";
    w.appendChild(l);w.appendChild(bar);cats.appendChild(w);
  });
  if(!items.length)cats.innerHTML='<div class="muted">Nothing yet</div>';

  var list=$("list");list.innerHTML="";
  items.forEach(function(x){
    var r=document.createElement("div");r.className="item";
    var t=document.createElement("div");
    t.textContent=(x.desc||x.cat)+" · "+inr(x.amt);
    var sub=document.createElement("div");sub.className="muted";
    sub.textContent=x.cat+" · "+x.date;
    t.appendChild(sub);
    var d=document.createElement("button");d.type="button";d.className="del";d.textContent="Delete";
    d.onclick=function(){data.items=data.items.filter(function(y){return y.id!==x.id});save();render()};
    r.appendChild(t);r.appendChild(d);list.appendChild(r);
  });
  if(!items.length)list.innerHTML='<div class="muted">No entries this month</div>';
}

$("add").onclick=function(){
  var amt=parseFloat($("amt").value);
  if(!(amt>0))return;
  var dt=$("date").value||today;
  data.items.push({id:Date.now()+Math.random(),desc:$("desc").value.trim(),amt:amt,cat:$("cat").value,date:dt});
  $("desc").value="";$("amt").value="";
  $("month").value=dt.slice(0,7);
  save();render();
};
$("month").onchange=render;
$("budget").oninput=function(){data.budget=$("budget").value;save();render()};
render();
</script>
</body>
</html>
```
